"use client";

import { useEffect, useMemo, useState, useTransition } from "react";
import type { InputHTMLAttributes } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { AlertTriangle, ArrowDownLeft, ArrowUpRight, BookOpen, CalendarClock, CheckCircle2, ChevronRight, CreditCard, FileText, Filter, Landmark, LineChart, Pencil, Plus, ReceiptText, Search, Settings2, WalletCards } from "lucide-react";
import { clsx } from "clsx";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";
import type { CreateLancamentoPayload, FinBanco, FinCartao, FinCategoria, FinCentroResultado, FinCurso, FinFormaPagamento, FinLancamento, FinStatus, FinSubcategoria, FinTipo, FinanceiroContext } from "@/modules/financeiro/types";

const tabLabels = { geral: "Visão Geral", lancamentos: "Lançamentos", consultas: "Consultas", admin: "Admin", apoio: "Apoio" } as const;
const tabIcons = { geral: LineChart, lancamentos: ReceiptText, consultas: Search, admin: Settings2, apoio: BookOpen } as const;
type Tab = keyof typeof tabLabels;
type PeriodFilter = "mes" | "mes_anterior" | "30d" | "90d" | "ano" | "personalizado" | "tudo";
type DateBasis = "caixa" | "competencia";
type QuickFilter = "todos" | "pendentes" | "previstos" | "realizados" | "vencidos";
type Maps = { centroById: Map<string, FinCentroResultado>; categoriaById: Map<string, FinCategoria>; subcategoriaById: Map<string, FinSubcategoria>; bancoById: Map<string, FinBanco>; cartaoById: Map<string, FinCartao>; cursoById: Map<string, FinCurso> };
const PAGE_SIZE = 20;
const hoje = () => new Date().toISOString().slice(0, 10);
const primeiroDiaMes = (date = new Date()) => `${date.toISOString().slice(0, 7)}-01`;
const periodLabels: Record<PeriodFilter, string> = { mes: "Este mês", mes_anterior: "Mês anterior", "30d": "Últimos 30 dias", "90d": "Últimos 90 dias", ano: "Este ano", personalizado: "Personalizado", tudo: "Todo o histórico" };
const quickLabels: Record<QuickFilter, string> = { todos: "Todos", pendentes: "Pendentes de classificação", previstos: "Previstos", realizados: "Pagos/Recebidos", vencidos: "Vencidos" };

function money(value: number, compact = false) { return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: compact ? 0 : 2 }).format(value || 0); }
function dateLabel(value?: string | null) { if (!value) return "Sem data"; return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "2-digit", year: "2-digit" }).format(new Date(`${value.slice(0, 10)}T12:00:00`)); }
function monthLabel(value: string) { return new Intl.DateTimeFormat("pt-BR", { month: "short", year: "2-digit" }).format(new Date(`${value.slice(0, 7)}-01T12:00:00`)).replace(".", ""); }
function updatedAtLabel(value: string | null) { if (!value) return "Base financeira sem atualização registrada"; return `Dados atualizados em ${new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "2-digit", year: "2-digit", hour: "2-digit", minute: "2-digit" }).format(new Date(value))}`; }
function parseCurrencyInput(value: string) { return Number(value.replace(/\D/g, "") || "0") / 100; }
function formatCurrencyInput(value: number) { return money(value); }
function idMap<T extends { id: string }>(rows: T[]) { return new Map(rows.map((row) => [row.id, row])); }
function isPendingClassification(row: FinLancamento) { return row.classificacao_status === "review" || !row.categoria_id || !row.subcategoria_id || !row.centro_resultado_id; }
function dueDate(row: FinLancamento) { return (row.data_vencimento ?? row.data_pagamento).slice(0, 10); }
function periodRange(period: PeriodFilter, customStart: string, customEnd: string) { const now = new Date(); if (period === "personalizado") return { start: customStart, end: customEnd }; if (period === "tudo") return { start: "1900-01-01", end: "2999-12-31" }; if (period === "mes") return { start: primeiroDiaMes(now), end: hoje() }; if (period === "mes_anterior") { const start = new Date(now.getFullYear(), now.getMonth() - 1, 1); const end = new Date(now.getFullYear(), now.getMonth(), 0); return { start: start.toISOString().slice(0, 10), end: end.toISOString().slice(0, 10) }; } if (period === "ano") return { start: `${now.getFullYear()}-01-01`, end: hoje() }; const days = period === "90d" ? 90 : 30; const start = new Date(now); start.setDate(now.getDate() - days); return { start: start.toISOString().slice(0, 10), end: hoje() }; }
function effectiveDate(row: FinLancamento, basis: DateBasis) { if (basis === "competencia") return row.mes_competencia.slice(0, 10); if (row.status === "realizado") return (row.data_realizacao ?? row.data_pagamento).slice(0, 10); return (row.data_vencimento ?? row.data_pagamento).slice(0, 10); }
function inRange(row: FinLancamento, start: string, end: string, basis: DateBasis = "caixa") { const date = effectiveDate(row, basis); return date >= start && date <= end; }
function statusLabel(row: Pick<FinLancamento, "tipo" | "status" | "data_vencimento" | "data_pagamento">) { if (row.status === "cancelado") return "Cancelado"; const due = (row.data_vencimento ?? row.data_pagamento).slice(0, 10); if (row.status === "previsto" && due < hoje()) return "Vencido"; if (row.status === "previsto") return "Previsto"; return row.tipo === "entrada" ? "Recebido" : "Pago"; }
function taxonomyLabel(value?: string | null) { if (value === "nao_operacional") return "Não operacional"; if (value === "nao_aplicavel") return "Não aplicável"; if (value === "fixo") return "Fixo"; if (value === "variavel") return "Variável"; return "Operacional"; }
function emptyLancamentoForm(context: FinanceiroContext): CreateLancamentoPayload { const tipo: FinTipo = "saida"; return { tipo, status: "realizado", data_pagamento: hoje(), data_vencimento: hoje(), data_realizacao: hoje(), mes_competencia: primeiroDiaMes(), natureza_fluxo: "operacional", comportamento: "variavel", centro_resultado_id: context.centros.find((item) => item.ativo)?.id ?? "", categoria_id: context.categorias.find((item) => item.ativo && item.tipo === tipo)?.id ?? "", subcategoria_id: null, curso_id: null, forma_pagamento: "conta_bancaria", banco_id: context.bancos.find((item) => item.ativo)?.id ?? null, cartao_id: null, qtd_parcelas: 1, descricao: "", valor: 0, observacao: "", responsavel: "" }; }
function lancamentoToForm(row: FinLancamento): CreateLancamentoPayload { return { tipo: row.tipo, status: row.status, data_pagamento: row.data_pagamento.slice(0, 10), data_vencimento: (row.data_vencimento ?? row.data_pagamento).slice(0, 10), data_realizacao: row.data_realizacao?.slice(0, 10) ?? (row.status === "realizado" ? row.data_pagamento.slice(0, 10) : null), mes_competencia: row.mes_competencia.slice(0, 10), natureza_fluxo: row.natureza_fluxo ?? "operacional", comportamento: row.comportamento ?? "nao_aplicavel", centro_resultado_id: row.centro_resultado_id, categoria_id: row.categoria_id, subcategoria_id: row.subcategoria_id, curso_id: row.curso_id, forma_pagamento: row.forma_pagamento, banco_id: row.banco_id, cartao_id: row.cartao_id, qtd_parcelas: row.qtd_parcelas, descricao: row.descricao, valor: row.valor, observacao: row.observacao, responsavel: row.responsavel ?? "" }; }
function parseTab(value: string | null, isAdmin: boolean): Tab { if (value === "lancamentos" || value === "consultas" || value === "apoio" || value === "geral") return value; if (value === "admin" && isAdmin) return "admin"; return "geral"; }
function parseQuick(value: string | null): QuickFilter { return value === "pendentes" || value === "previstos" || value === "realizados" || value === "vencidos" ? value : "todos"; }

export function FinanceiroDashboard({ context }: { context: FinanceiroContext }) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const isAdmin = context.perfil === "admin";
  const [activeTab, setActiveTab] = useState<Tab>(() => parseTab(searchParams.get("view"), isAdmin));
  const [period, setPeriod] = useState<PeriodFilter>("tudo");
  const [customStart, setCustomStart] = useState(primeiroDiaMes());
  const [customEnd, setCustomEnd] = useState(hoje());
  const [message, setMessage] = useState<string | null>(null);
  const [editing, setEditing] = useState<FinLancamento | null>(null);
  const [isPending, startTransition] = useTransition();
  const quickFilter = parseQuick(searchParams.get("status"));
  const highlightId = searchParams.get("highlight");
  const canEdit = context.perfil === "admin" || context.perfil === "suporte" || context.perfil === "especialista";
  const visibleTabs = useMemo<Tab[]>(() => isAdmin ? ["geral", "lancamentos", "consultas", "admin", "apoio"] : ["geral", "lancamentos", "consultas", "apoio"], [isAdmin]);
  const maps = useMemo<Maps>(() => ({ centroById: idMap(context.centros), categoriaById: idMap(context.categorias), subcategoriaById: idMap(context.subcategorias), bancoById: idMap(context.bancos), cartaoById: idMap(context.cartoes), cursoById: idMap(context.cursos) }), [context]);
  useEffect(() => { setActiveTab(parseTab(searchParams.get("view"), isAdmin)); }, [isAdmin, searchParams]);
  function updateView(tab: Tab, params?: Record<string, string | null>) { const next = new URLSearchParams(searchParams.toString()); next.set("view", tab); Object.entries(params ?? {}).forEach(([key, value]) => { if (value) next.set(key, value); else next.delete(key); }); router.push(`/financeiro?${next.toString()}`); setActiveTab(tab); }
  function notify(text: string) { setMessage(text); window.setTimeout(() => setMessage(null), 4500); }
  function deleteLancamento(row: FinLancamento) { if (!canEdit || !window.confirm(`Excluir o lançamento "${row.descricao}"?`)) return; startTransition(async () => { const response = await fetch("/api/financeiro/lancamentos", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: row.id }) }); const payload = await response.json().catch(() => ({})); if (!response.ok) { notify(payload.error ?? "Falha ao excluir lançamento."); return; } notify("Lançamento excluído."); router.refresh(); }); }
  if (context.diagnostic) return <Card className="mx-auto max-w-3xl p-6"><p className="text-sm font-bold uppercase text-brand-clay">Financeiro</p><h1 className="mt-2 text-3xl font-semibold text-brand-teal">Acesso ainda não disponível</h1><p className="mt-3 text-sm leading-6 text-brand-teal/70">{context.diagnostic}</p></Card>;
  return <section className="norwyn-ds-page mx-auto max-w-[1540px] space-y-8 px-1"><header className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-start"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-[color:var(--ds-accent)]">Norwyn OS</p><h1 className="mt-2 text-4xl font-semibold tracking-tight text-[color:var(--ds-text)] sm:text-5xl">Financeiro</h1><p className="mt-3 max-w-3xl text-sm leading-6 text-[color:var(--ds-text-secondary)] sm:text-base">Controle, clareza e tranquilidade para o seu negócio crescer.</p></div><div className="flex flex-col items-start gap-3 pt-2 lg:items-end"><div className="rounded-full border border-[color:var(--ds-border)] bg-[color:var(--ds-surface-solid)] px-5 py-2.5 text-sm font-semibold text-[color:var(--ds-text)] shadow-[var(--ds-shadow-sm)]">Este mês · Setembro/2026</div><div className="text-xs font-medium text-[color:var(--ds-text-muted)]">{updatedAtLabel(context.updatedAt)}</div></div></header><nav className="flex w-full flex-wrap gap-3">{visibleTabs.map((tab) => <button key={tab} type="button" onClick={() => updateView(tab)} className={clsx("flex items-center justify-center gap-2 rounded-full border px-4 py-2 text-sm font-semibold transition", activeTab === tab ? "border-brand-teal bg-brand-teal text-white shadow-soft" : "border-[color:var(--ds-border)] bg-[color:var(--ds-surface-solid)] text-[color:var(--ds-text-secondary)] hover:border-brand-teal/30 hover:bg-white hover:text-brand-teal")}>{(() => { const Icon = tabIcons[tab]; return <><Icon className="h-4 w-4" />{tabLabels[tab]}</>; })()}</button>)}</nav>{message ? <div className="rounded-xl border border-brand-sand bg-white/85 px-4 py-3 text-sm font-semibold text-brand-teal shadow-soft">{message}</div> : null}{activeTab === "geral" ? <VisaoGeral context={context} maps={maps} period={period} setPeriod={setPeriod} customStart={customStart} setCustomStart={setCustomStart} customEnd={customEnd} setCustomEnd={setCustomEnd} onNavigate={updateView} onOpenLancamento={(row) => { setEditing(row); updateView("lancamentos", { status: isPendingClassification(row) ? "pendentes" : null, highlight: row.id }); }} /> : null}{activeTab === "lancamentos" ? <LancamentosTab context={context} maps={maps} canEdit={canEdit} editing={editing} setEditing={setEditing} isPending={isPending} startTransition={startTransition} notify={notify} onDelete={deleteLancamento} initialQuick={quickFilter} highlightId={highlightId} /> : null}{activeTab === "consultas" ? <ConsultasTab context={context} maps={maps} /> : null}{activeTab === "admin" && isAdmin ? <AdminTab context={context} /> : null}{activeTab === "apoio" ? <ApoioTab /> : null}</section>;
}

function VisaoGeral({ context, maps, period, setPeriod, customStart, setCustomStart, customEnd, setCustomEnd, onNavigate, onOpenLancamento }: { context: FinanceiroContext; maps: Maps; period: PeriodFilter; setPeriod: (value: PeriodFilter) => void; customStart: string; setCustomStart: (value: string) => void; customEnd: string; setCustomEnd: (value: string) => void; onNavigate: (tab: Tab, params?: Record<string, string | null>) => void; onOpenLancamento: (row: FinLancamento) => void }) {
  const range = periodRange(period, customStart, customEnd);
  const rows = context.lancamentos.filter((row) => inRange(row, range.start, range.end));
  const entradas = rows.filter((row) => row.tipo === "entrada" && row.status === "realizado").reduce((sum, row) => sum + row.valor, 0);
  const saidas = rows.filter((row) => row.tipo === "saida" && row.status === "realizado").reduce((sum, row) => sum + row.valor, 0);
  const receber = rows.filter((row) => row.tipo === "entrada" && row.status === "previsto").reduce((sum, row) => sum + row.valor, 0);
  const pagar = rows.filter((row) => row.tipo === "saida" && row.status === "previsto").reduce((sum, row) => sum + row.valor, 0);
  const today = hoje(); const next30 = new Date(); next30.setDate(next30.getDate() + 30); const next30Iso = next30.toISOString().slice(0, 10);
  const upcoming = (tipo: FinTipo) => context.lancamentos.filter((row) => row.tipo === tipo && row.status === "previsto" && (row.data_vencimento ?? row.data_pagamento).slice(0, 10) >= today && (row.data_vencimento ?? row.data_pagamento).slice(0, 10) <= next30Iso).sort((a, b) => (a.data_vencimento ?? a.data_pagamento).localeCompare(b.data_vencimento ?? b.data_pagamento)).slice(0, 5);
  const vencidos = context.lancamentos.filter((row) => row.status === "previsto" && (row.data_vencimento ?? row.data_pagamento).slice(0, 10) < today);
  const semClassificacao = context.lancamentos.filter(isPendingClassification); const pending = semClassificacao[0];
  const mensal = buildMonthlyFlow(rows);
  return <div className="space-y-7"><div className="flex flex-wrap items-center gap-3 rounded-2xl border border-brand-sand/70 bg-white/70 p-3 shadow-soft"><Select compact label="Período" value={period} onChange={(value) => setPeriod(value as PeriodFilter)} options={Object.entries(periodLabels)} />{period === "personalizado" ? <Field label="Início" type="date" value={customStart} onChange={setCustomStart} /> : null}{period === "personalizado" ? <Field label="Fim" type="date" value={customEnd} onChange={setCustomEnd} /> : null}<span className="rounded-full bg-brand-cream px-4 py-2 text-xs font-black text-brand-teal/65">Período: {dateLabel(range.start)} → {dateLabel(range.end)}</span></div><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-5"><MetricCard title="Entrou na conta" value={money(entradas, true)} detail="Caixa realizado" tone="green" Icon={ArrowDownLeft} /><MetricCard title="Saiu da conta" value={money(saidas, true)} detail="Pagamentos realizados" tone="rose" Icon={ArrowUpRight} /><MetricCard title="Saldo do período" value={money(entradas - saidas, true)} detail="Entradas - Saídas" tone={entradas - saidas >= 0 ? "teal" : "rose"} Icon={WalletCards} /><MetricCard title="A receber" value={money(receber, true)} detail="Previsto no período" tone="blue" Icon={CalendarClock} /><MetricCard title="A pagar" value={money(pagar, true)} detail="Previsto no período" tone="gold" Icon={ReceiptText} /></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1.45fr)_minmax(380px,0.55fr)]"><Card className="rounded-2xl p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div className="flex gap-4"><ToneIcon tone="blue" Icon={LineChart} /><div><h2 className="text-2xl font-black text-brand-teal">Fluxo de caixa</h2><p className="mt-1 text-sm font-semibold text-brand-teal/60">Entradas e saídas observadas no período selecionado.</p></div></div><div className="flex gap-4 text-xs font-black text-brand-teal/60"><span className="flex items-center gap-2"><i className="h-2.5 w-2.5 rounded-full bg-emerald-500" />Entradas</span><span className="flex items-center gap-2"><i className="h-2.5 w-2.5 rounded-full bg-brand-clay" />Saídas</span></div></div><FlowChart rows={mensal} />{mensal.length === 0 ? <EmptyState text="Sem lançamentos para o período." /> : null}</Card><Card className="rounded-2xl p-7"><div className="flex items-center gap-4"><ToneIcon tone="gold" Icon={AlertTriangle} /><div><p className="text-xs font-black uppercase tracking-[0.16em] text-brand-clay">Precisa de você</p><h2 className="text-2xl font-black text-brand-teal">O que precisa de atenção</h2></div></div><div className="mt-5 space-y-3"><AttentionItem title={String(semClassificacao.length) + " pendente(s) de classificação"} detail={pending ? pending.descricao + " · " + dateLabel(pending.data_pagamento) : "Tudo classificado nesta base."} active={semClassificacao.length > 0} onClick={() => onNavigate("lancamentos", { status: "pendentes", highlight: pending?.id ?? null })} /><AttentionItem title={String(vencidos.length) + " lançamento(s) vencido(s)"} detail="Previstos com vencimento anterior a hoje." active={vencidos.length > 0} onClick={() => onNavigate("lancamentos", { status: "vencidos", highlight: null })} /><AttentionItem title={String(upcoming("saida").length) + " pagamento(s) nos próximos 30 dias"} detail="Fluxo futuro baseado apenas em lançamentos previstos." active={upcoming("saida").length > 0} onClick={() => onNavigate("lancamentos", { status: "previstos", highlight: null })} /></div><div className="mt-5 rounded-2xl bg-brand-cream/65 p-5 text-sm leading-6 text-brand-teal/75"><p><strong>Dado observado:</strong> o saldo do período é caixa realizado.</p><p><strong>Inferência:</strong> previsões só consideram vencimentos cadastrados.</p><p><strong>Recomendação:</strong> completar contas previstas antes de usar projeção de caixa para decisão.</p></div></Card></div><div className="grid gap-5 xl:grid-cols-2"><MovementList title="Próximos recebimentos" rows={upcoming("entrada")} maps={maps} empty="Nenhum recebimento previsto nos próximos 30 dias." onOpen={onOpenLancamento} onSeeAll={() => onNavigate("lancamentos", { status: "previstos", highlight: null })} /><MovementList title="Próximos pagamentos" rows={upcoming("saida")} maps={maps} empty="Nenhum pagamento previsto nos próximos 30 dias." onOpen={onOpenLancamento} onSeeAll={() => onNavigate("lancamentos", { status: "previstos", highlight: null })} /></div></div>;
}
function LancamentosTab({ context, maps, canEdit, editing, setEditing, isPending, startTransition, notify, onDelete, initialQuick, highlightId }: { context: FinanceiroContext; maps: Maps; canEdit: boolean; editing: FinLancamento | null; setEditing: (row: FinLancamento | null) => void; isPending: boolean; startTransition: ReturnType<typeof useTransition>[1]; notify: (text: string) => void; onDelete: (row: FinLancamento) => void; initialQuick: QuickFilter; highlightId: string | null }) {
  const router = useRouter();
  const [form, setForm] = useState<CreateLancamentoPayload>(() => emptyLancamentoForm(context));
  const [query, setQuery] = useState(""); const [tipo, setTipo] = useState<"todos" | FinTipo>("todos"); const [status, setStatus] = useState<"todos" | FinStatus>("todos"); const [quick, setQuick] = useState<QuickFilter>(initialQuick); const [page, setPage] = useState(1);
  useEffect(() => { setQuick(initialQuick); setPage(1); }, [initialQuick]);
  useEffect(() => { if (editing) setForm(lancamentoToForm(editing)); }, [editing]);
  useEffect(() => { if (!highlightId) return; const node = document.querySelector(`[data-lancamento-id="${highlightId}"]`); node?.scrollIntoView({ behavior: "smooth", block: "center" }); }, [highlightId, quick, page]);
  const filtered = useMemo(() => { const needle = query.trim().toLowerCase(); return context.lancamentos.filter((row) => { if (tipo !== "todos" && row.tipo !== tipo) return false; if (status !== "todos" && row.status !== status) return false; if (quick === "pendentes" && !isPendingClassification(row)) return false; if (quick === "previstos" && row.status !== "previsto") return false; if (quick === "realizados" && row.status !== "realizado") return false; if (quick === "vencidos" && !(row.status === "previsto" && dueDate(row) < hoje())) return false; if (!needle) return true; const haystack = [row.descricao, maps.categoriaById.get(row.categoria_id)?.nome, maps.subcategoriaById.get(row.subcategoria_id ?? "")?.nome, maps.centroById.get(row.centro_resultado_id)?.nome].filter(Boolean).join(" ").toLowerCase(); return haystack.includes(needle); }); }, [context.lancamentos, maps, query, quick, status, tipo]);
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE)); const pageRows = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
  function resetForm() { setEditing(null); setForm(emptyLancamentoForm(context)); }
  function save() { if (!canEdit) return; startTransition(async () => { const response = await fetch("/api/financeiro/lancamentos", { method: editing ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...form, id: editing?.id }) }); const payload = await response.json().catch(() => ({})); if (!response.ok) { notify(payload.error ?? "Falha ao salvar lançamento."); return; } notify(editing ? "Lançamento atualizado." : "Lançamento criado."); resetForm(); router.refresh(); }); }
  function baixa(row: FinLancamento) { setEditing(row); setForm({ ...lancamentoToForm(row), status: "realizado", data_realizacao: hoje(), data_pagamento: hoje() }); notify("Revise os dados e salve para confirmar a baixa."); }
  return <div className="grid gap-6 xl:grid-cols-[minmax(0,1.35fr)_minmax(390px,0.65fr)]"><Card className="rounded-2xl p-6 xl:order-2"><div className="flex items-center gap-3"><Plus className="h-5 w-5 text-brand-clay" /><div><h2 className="text-xl font-black text-brand-teal">{editing ? "Editar lançamento" : "Novo lançamento"}</h2><p className="text-sm font-semibold text-brand-teal/60">{canEdit ? "Registre, classifique e acompanhe entradas e saídas do dia a dia." : "Seu perfil consulta lançamentos, mas não altera a base."}</p></div></div><div className="mt-6 grid gap-4"><Field label="Descrição" value={form.descricao} onChange={(value) => setForm({ ...form, descricao: value })} disabled={!canEdit} /><div className="grid gap-3 sm:grid-cols-2"><Select label="Tipo" value={form.tipo} onChange={(value) => setForm({ ...form, tipo: value as FinTipo, categoria_id: context.categorias.find((item) => item.ativo && item.tipo === value)?.id ?? "", subcategoria_id: null })} options={[["entrada", "Entrada"], ["saida", "Saída"]]} disabled={!canEdit} /><Select label="Status" value={form.status} onChange={(value) => setForm({ ...form, status: value as FinStatus, data_realizacao: value === "realizado" ? (form.data_realizacao || form.data_pagamento) : null })} options={[["previsto", "Previsto"], ["realizado", form.tipo === "entrada" ? "Recebido" : "Pago"], ["cancelado", "Cancelado"]]} disabled={!canEdit} /><Select label="Natureza do fluxo" value={form.natureza_fluxo ?? "operacional"} onChange={(value) => setForm({ ...form, natureza_fluxo: value as never })} options={[["operacional", "Operacional"], ["nao_operacional", "Não operacional"]]} disabled={!canEdit} /><Select label="Comportamento" value={form.comportamento ?? "nao_aplicavel"} onChange={(value) => setForm({ ...form, comportamento: value as never })} options={[["fixo", "Fixo"], ["variavel", "Variável"], ["nao_aplicavel", "Não aplicável"]]} disabled={!canEdit} /></div><div className="grid gap-3 sm:grid-cols-3"><Field label="Data" type="date" value={form.data_pagamento} onChange={(value) => setForm({ ...form, data_pagamento: value })} disabled={!canEdit} /><Field label="Vencimento" type="date" value={form.data_vencimento ?? form.data_pagamento} onChange={(value) => setForm({ ...form, data_vencimento: value })} disabled={!canEdit} /><Field label="Competência" type="month" value={form.mes_competencia.slice(0, 7)} onChange={(value) => setForm({ ...form, mes_competencia: `${value}-01` })} disabled={!canEdit} /></div><div className="grid gap-3 sm:grid-cols-2"><Select label="Centro" value={form.centro_resultado_id} onChange={(value) => setForm({ ...form, centro_resultado_id: value })} options={context.centros.filter((item) => item.ativo).map((item) => [item.id, item.nome])} disabled={!canEdit} /><Select label="Categoria" value={form.categoria_id} onChange={(value) => setForm({ ...form, categoria_id: value, subcategoria_id: null })} options={context.categorias.filter((item) => item.ativo && item.tipo === form.tipo).map((item) => [item.id, item.nome])} disabled={!canEdit} /><Select label="Subcategoria" value={form.subcategoria_id ?? ""} onChange={(value) => setForm({ ...form, subcategoria_id: value || null })} options={[["", "Sem subcategoria"], ...context.subcategorias.filter((item) => item.ativo && item.categoria_id === form.categoria_id).map((item) => [item.id, item.nome] as [string, string])]} disabled={!canEdit} /><Select label="Produto/curso" value={form.curso_id ?? ""} onChange={(value) => setForm({ ...form, curso_id: value || null })} options={[["", "Não aplicável"], ...context.cursos.filter((item) => item.ativo).map((item) => [item.id, item.nome] as [string, string])]} disabled={!canEdit} /></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor" value={formatCurrencyInput(form.valor)} onChange={(value) => setForm({ ...form, valor: parseCurrencyInput(value) })} disabled={!canEdit} /><Select label="Forma de pagamento" value={form.forma_pagamento} onChange={(value) => setForm({ ...form, forma_pagamento: value as FinFormaPagamento })} options={[["conta_bancaria", "Conta bancária"], ["cartao_credito", "Cartão de crédito"], ["pix", "Pix"], ["boleto", "Boleto"], ["dinheiro", "Dinheiro"]]} disabled={!canEdit} />{form.forma_pagamento === "cartao_credito" ? <Select label="Cartão" value={form.cartao_id ?? ""} onChange={(value) => setForm({ ...form, cartao_id: value || null, banco_id: null })} options={context.cartoes.filter((item) => item.ativo).map((item) => [item.id, item.nome])} disabled={!canEdit} /> : <Select label="Banco/conta" value={form.banco_id ?? ""} onChange={(value) => setForm({ ...form, banco_id: value || null, cartao_id: null })} options={context.bancos.filter((item) => item.ativo).map((item) => [item.id, item.nome])} disabled={!canEdit} />}<Field label="Responsável" value={form.responsavel ?? ""} onChange={(value) => setForm({ ...form, responsavel: value })} disabled={!canEdit} /></div><Field label="Observação" value={form.observacao ?? ""} onChange={(value) => setForm({ ...form, observacao: value })} disabled={!canEdit} />{canEdit ? <div className="flex flex-wrap gap-2"><Button disabled={isPending} onClick={save}>{editing ? "Salvar alteração" : "Salvar lançamento"}</Button>{editing ? <Button variant="secondary" onClick={resetForm}>Cancelar edição</Button> : null}</div> : null}</div></Card><Card className="rounded-2xl p-6 xl:order-1"><div className="mb-4 flex flex-wrap items-center gap-2"><Filter className="h-5 w-5 text-brand-clay" />{(Object.keys(quickLabels) as QuickFilter[]).map((item) => <button key={item} type="button" onClick={() => { setQuick(item); setPage(1); }} className={clsx("rounded-full border px-4 py-2 text-sm font-black transition", quick === item ? "border-brand-teal bg-brand-teal text-white shadow-sm" : "border-brand-sand/70 bg-white/80 text-brand-teal/75 hover:bg-white hover:text-brand-teal")}>{quickLabels[item]}{item === "pendentes" ? ` (${context.lancamentos.filter(isPendingClassification).length})` : ""}</button>)}</div><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-xl font-black text-brand-teal">Lançamentos</h2><p className="text-sm font-semibold text-brand-teal/60">{filtered.length} registro(s) encontrados · página {page} de {totalPages}</p></div><div className="flex flex-wrap gap-2"><Field compact label="Buscar" value={query} onChange={(value) => { setQuery(value); setPage(1); }} placeholder="Descrição, categoria..." /><Select compact label="Tipo" value={tipo} onChange={(value) => { setTipo(value as never); setPage(1); }} options={[["todos", "Todos"], ["entrada", "Entradas"], ["saida", "Saídas"]]} /><Select compact label="Status" value={status} onChange={(value) => { setStatus(value as never); setPage(1); }} options={[["todos", "Todos"], ["previsto", "Previsto"], ["realizado", "Pago/Recebido"], ["cancelado", "Cancelado"]]} /></div></div><div className="mt-6 overflow-hidden rounded-2xl border border-brand-sand/60 bg-white/50"><div className="hidden bg-brand-cream/55 px-5 py-4 text-xs font-black uppercase tracking-wide text-brand-teal/50 md:grid md:grid-cols-[1.1fr_0.8fr_0.8fr_0.8fr_0.7fr_auto] md:gap-3"><span>Descrição</span><span>Classificação</span><span>Data</span><span>Status</span><span>Valor</span><span>Ações</span></div>{pageRows.map((row) => <LancamentoRow key={row.id} row={row} maps={maps} canEdit={canEdit} highlighted={row.id === highlightId} onEdit={() => setEditing(row)} onDelete={() => onDelete(row)} onBaixar={() => baixa(row)} />)}{pageRows.length === 0 ? <EmptyState text="Nenhum lançamento encontrado." /> : null}</div><Pager page={page} totalPages={totalPages} setPage={setPage} /></Card></div>;
}

function ConsultasTab({ context, maps }: { context: FinanceiroContext; maps: Maps }) { const [period, setPeriod] = useState<PeriodFilter>("90d"); const [basis, setBasis] = useState<DateBasis>("caixa"); const [customStart, setCustomStart] = useState(primeiroDiaMes()); const [customEnd, setCustomEnd] = useState(hoje()); const [centro, setCentro] = useState("todos"); const [categoria, setCategoria] = useState("todos"); const [tipo, setTipo] = useState("todos"); const [status, setStatus] = useState("todos"); const range = periodRange(period, customStart, customEnd); const rows = context.lancamentos.filter((row) => inRange(row, range.start, range.end, basis) && (centro === "todos" || row.centro_resultado_id === centro) && (categoria === "todos" || row.categoria_id === categoria) && (tipo === "todos" || row.tipo === tipo) && (status === "todos" || row.status === status)); const entradas = rows.filter((row) => row.tipo === "entrada" && row.status !== "cancelado").reduce((sum, row) => sum + row.valor, 0); const saidas = rows.filter((row) => row.tipo === "saida" && row.status !== "cancelado").reduce((sum, row) => sum + row.valor, 0); const previstos = rows.filter((row) => row.status === "previsto").reduce((sum, row) => sum + row.valor, 0); const byCategory = groupTotals(rows, (row) => maps.categoriaById.get(row.categoria_id)?.nome ?? "Sem categoria"); const byCenter = groupTotals(rows, (row) => maps.centroById.get(row.centro_resultado_id)?.nome ?? "Sem centro"); const months = buildMonthlyFlow(rows); return <div className="space-y-7"><Card className="rounded-2xl p-5"><div className="flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-4"><ToneIcon tone="blue" Icon={Search} /><div><h2 className="text-2xl font-black text-brand-teal">Consultas</h2><p className="text-sm font-semibold text-brand-teal/60">Caixa, competência e recortes sem misturar conceitos.</p></div></div><span className="rounded-full bg-brand-cream px-4 py-2 text-xs font-black text-brand-teal/65">{rows.length} lançamento(s)</span></div><div className="mt-5 grid gap-3 md:grid-cols-3 xl:grid-cols-6"><Select label="Período" value={period} onChange={(value) => setPeriod(value as PeriodFilter)} options={Object.entries(periodLabels)} /><Select label="Visão" value={basis} onChange={(value) => setBasis(value as DateBasis)} options={[["caixa", "Caixa"], ["competencia", "Competência"]]} /><Select label="Centro" value={centro} onChange={setCentro} options={[["todos", "Todos"], ...context.centros.map((item) => [item.id, item.nome] as [string, string])]} /><Select label="Categoria" value={categoria} onChange={setCategoria} options={[["todos", "Todas"], ...context.categorias.map((item) => [item.id, item.nome] as [string, string])]} /><Select label="Tipo" value={tipo} onChange={setTipo} options={[["todos", "Todos"], ["entrada", "Entrada"], ["saida", "Saída"]]} /><Select label="Status" value={status} onChange={setStatus} options={[["todos", "Todos"], ["previsto", "Previsto"], ["realizado", "Pago/Recebido"], ["cancelado", "Cancelado"]]} />{period === "personalizado" ? <Field label="Início" type="date" value={customStart} onChange={setCustomStart} /> : null}{period === "personalizado" ? <Field label="Fim" type="date" value={customEnd} onChange={setCustomEnd} /> : null}</div><p className="mt-4 text-sm font-semibold text-brand-teal/60">Período: {dateLabel(range.start)} a {dateLabel(range.end)} · visão por {basis === "caixa" ? "caixa" : "competência"}</p></Card><div className="grid gap-5 md:grid-cols-3"><MiniMetric title="Entradas" value={money(entradas, true)} tone="green" Icon={ArrowDownLeft} /><MiniMetric title="Saídas" value={money(saidas, true)} tone="rose" Icon={ArrowUpRight} /><MiniMetric title="Previsto" value={money(previstos, true)} tone="gold" Icon={CalendarClock} /></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]"><SummaryList title="Por categoria" rows={byCategory} /><SummaryList title="Por centro" rows={byCenter} /></div><Card className="rounded-2xl p-7"><div className="flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-4"><ToneIcon tone="blue" Icon={LineChart} /><div><h3 className="text-2xl font-black text-brand-teal">Mês a mês</h3><p className="text-sm font-semibold text-brand-teal/60">Comparativo visual de entradas e saídas.</p></div></div><span className="rounded-full bg-white px-4 py-2 text-xs font-black text-brand-teal/60 shadow-soft">Valores em reais</span></div><div className="mt-6"><FlowChart rows={months} compact /></div></Card></div>; }
function AdminTab({ context }: { context: FinanceiroContext }) { const categories = context.categorias.filter((item) => item.ativo); const subcategories = context.subcategorias.filter((item) => item.ativo); const centros = context.centros.filter((item) => item.ativo); const contas = context.bancos.length + context.cartoes.length; const profiles = [{ name: "Admin", detail: "Acesso total ao módulo financeiro.", badge: "Acesso total", tone: "green" }, { name: "Especialista", detail: "Visão executiva, lançamentos e consultas.", badge: "Acesso padrão", tone: "blue" }, { name: "Operacional", detail: "Lançamentos e consultas do dia a dia.", badge: "Operação", tone: "gold" }, { name: "Suporte", detail: "Consulta e apoio operacional.", badge: "Somente leitura", tone: "blue" }]; return <div className="space-y-5"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5"><AdminStat title="Categorias" value={String(categories.length)} detail="categorias ativas" tone="violet" Icon={FileText} /><AdminStat title="Subcategorias" value={String(subcategories.length)} detail="subcategorias ativas" tone="blue" Icon={BookOpen} /><AdminStat title="Centros de resultado" value={String(centros.length)} detail="centros ativos" tone="green" Icon={Landmark} /><AdminStat title="Contas e cartões" value={String(contas)} detail="meios cadastrados" tone="gold" Icon={CreditCard} /><AdminStat title="Perfis de acesso" value={String(profiles.length)} detail="perfis cadastrados" tone="rose" Icon={Settings2} /></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1.35fr)_minmax(380px,0.65fr)]"><Card className="rounded-xl p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-black text-brand-teal">Taxonomia financeira</h2><p className="mt-1 text-sm font-semibold text-brand-teal/60">Estruture e gerencie a classificação dos lançamentos.</p></div><span className="rounded-full bg-brand-cream px-4 py-2 text-sm font-black text-brand-teal/70">Taxonomia ativa</span></div><div className="mt-5 overflow-hidden rounded-xl border border-brand-sand/70"><div className="grid grid-cols-[1fr_1.3fr_0.7fr_auto] gap-3 bg-brand-cream/80 px-4 py-3 text-xs font-black uppercase text-brand-teal/60"><span>Nome do tipo</span><span>Descrição</span><span>Status</span><span>Ações</span></div>{categories.slice(0, 8).map((category) => <div key={category.id} className="grid grid-cols-[1fr_1.3fr_0.7fr_auto] items-center gap-3 border-t border-brand-sand/70 bg-white/55 px-4 py-3"><div><p className="font-black text-brand-teal">{category.nome}</p><p className="text-xs font-semibold text-brand-teal/50">{category.tipo === "entrada" ? "Entrada" : "Saída"}</p></div><p className="text-sm font-semibold text-brand-teal/65">{taxonomyLabel(category.natureza_fluxo_padrao)} · {taxonomyLabel(category.comportamento_padrao)}</p><span className="w-fit rounded-full bg-emerald-50 px-3 py-1 text-xs font-black text-emerald-700">Ativo</span><Pencil className="h-4 w-4 text-brand-teal/55" /></div>)}</div></Card><div className="space-y-5"><Card className="rounded-xl p-5"><div className="flex items-center justify-between gap-3"><div><h2 className="text-xl font-black text-brand-teal">Perfis e permissões</h2><p className="mt-1 text-sm font-semibold text-brand-teal/60">Defina quem pode acessar cada informação.</p></div><ChevronRight className="h-5 w-5 text-brand-teal/45" /></div><div className="mt-4 space-y-3">{profiles.map((profile) => <div key={profile.name} className="grid grid-cols-[42px_1fr_auto] items-center gap-3"><span className={clsx("flex h-10 w-10 items-center justify-center rounded-full text-sm font-black", profile.tone === "green" ? "bg-emerald-100 text-emerald-700" : profile.tone === "gold" ? "bg-brand-sand/70 text-brand-teal" : "bg-brand-sky/30 text-brand-teal")}>{profile.name[0]}</span><div><p className="font-black text-brand-teal">{profile.name}</p><p className="text-xs font-semibold text-brand-teal/55">{profile.detail}</p></div><span className="rounded-full bg-brand-cream px-3 py-1 text-xs font-black text-brand-teal/65">{profile.badge}</span></div>)}</div></Card><Card className="rounded-xl p-5"><h2 className="text-xl font-black text-brand-teal">Integrações e origem dos dados</h2><div className="mt-4 space-y-3"><IntegrationRow name="Planilha Ju/Ryan" detail="Lançamentos manuais" status="Manual" tone="blue" /><IntegrationRow name="Hotmart" detail="Vendas e comissões" status="Conectado" tone="green" /><IntegrationRow name="Meta Ads" detail="Despesas de anúncios" status="Conectado" tone="green" /><IntegrationRow name="Bancos" detail="Extrato bancário" status="Em revisão" tone="gold" /><IntegrationRow name="Cartões" detail="Faturas dos cartões" status="Conectado" tone="green" /></div></Card></div></div><Card className="rounded-xl p-5"><div className="flex items-center justify-between gap-3"><div><h2 className="text-xl font-black text-brand-teal">Validação e padronização</h2><p className="mt-1 text-sm font-semibold text-brand-teal/60">Revise sugestões de mapeamento e nomes que precisam de cuidado.</p></div><span className="text-sm font-black text-brand-clay">Sugestões reais</span></div><div className="mt-4 grid gap-3 md:grid-cols-3"><ValidationMini label="Automático" count={categories.length + subcategories.length} tone="green" /><ValidationMini label="Em revisão" count={context.lancamentos.filter(isPendingClassification).length} tone="gold" /><ValidationMini label="Duplicidades" count={0} tone="rose" /></div></Card></div>; }
function ApoioTab() { const examples = [["Venda confirmada da Hotmart", "Recebimento de uma venda de curso na plataforma.", "Entrada", "Operacional", "Variável", "Receitas", "Infoprodutos", "Recebido"], ["Mensalidade de ferramenta", "Pagamento de mensalidade do Notion ou CRM.", "Saída", "Operacional", "Fixo", "Tecnologia & Ferramentas", "Infoprodutos", "Pago"], ["Distribuição de lucros", "Transferência de lucro para os sócios.", "Saída", "Não operacional", "Não aplicável", "Distribuição aos Sócios", "Não operacional", "Pago"]]; const questions = ["Qual a diferença entre Caixa e Competência?", "Qual categoria usar para cada tipo de despesa?", "Preciso anexar comprovante sempre?", "Posso editar um lançamento depois de salvo?"]; return <div className="space-y-5"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><ConceptCard Icon={ArrowDownLeft} title="O que entra na conta?" text="Receitas que aumentam o saldo, como vendas, recebimentos e aportes." tone="green" /><ConceptCard Icon={ArrowUpRight} title="O que sai da conta?" text="Despesas que diminuem o saldo, como ferramentas, impostos e retiradas." tone="rose" /><ConceptCard Icon={Landmark} title="Caixa x Competência" text="Caixa é quando o dinheiro entra ou sai. Competência é o mês de referência." tone="blue" /><ConceptCard Icon={FileText} title="Como preencher" text="Use os exemplos e o checklist para registrar sem dúvida." tone="gold" /></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1.45fr)_minmax(380px,0.55fr)]"><Card className="rounded-xl p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-black text-brand-teal">Exemplos práticos</h2><p className="mt-1 text-sm font-semibold text-brand-teal/60">Veja como classificar os lançamentos mais comuns no dia a dia.</p></div><span className="text-sm font-black text-brand-clay">Exemplos guiados</span></div><div className="mt-5 space-y-3">{examples.map((item) => <div key={item[0]} className="grid gap-3 rounded-xl border border-brand-sand/70 bg-white/70 p-4 lg:grid-cols-[1.2fr_repeat(6,auto)] lg:items-center"><div><p className="font-black text-brand-teal">{item[0]}</p><p className="text-sm font-semibold text-brand-teal/55">{item[1]}</p></div>{item.slice(2).map((label) => <span key={label} className="w-fit rounded-lg bg-brand-cream px-3 py-1 text-xs font-black text-brand-teal/70">{label}</span>)}</div>)}</div></Card><Card className="rounded-xl p-5"><div className="flex items-center gap-3"><CheckCircle2 className="h-6 w-6 text-emerald-600" /><div><h2 className="text-xl font-black text-brand-teal">Checklist antes de salvar</h2><p className="text-sm font-semibold text-brand-teal/60">Revise para evitar retrabalho.</p></div></div><div className="mt-5 space-y-3">{["O valor está correto?", "A data está no período certo?", "Categoria e subcategoria estão adequadas?", "O centro de resultado foi selecionado?", "O status está correto?", "A observação contém o contexto necessário?"].map((item) => <label key={item} className="flex items-center gap-3 text-sm font-bold text-brand-teal/75"><span className="h-4 w-4 rounded border border-brand-teal/35 bg-white" />{item}</label>)}</div><div className="mt-5 rounded-xl bg-emerald-50 p-4 text-sm font-bold text-emerald-800">Tudo certo? Assim seu financeiro fica mais organizado e confiável.</div></Card></div><div className="grid gap-5 xl:grid-cols-3"><Card className="rounded-xl p-5"><h2 className="text-xl font-black text-brand-teal">Perguntas frequentes</h2><div className="mt-4 space-y-2">{questions.map((item) => <div key={item} className="flex w-full items-center justify-between rounded-lg border border-brand-sand/70 bg-white/70 px-4 py-3 text-left text-sm font-black text-brand-teal"><span>{item}</span><ChevronRight className="h-4 w-4" /></div>)}</div></Card><Card className="rounded-xl p-5"><h2 className="text-xl font-black text-brand-teal">Erros comuns</h2><div className="mt-4 space-y-3"><ErrorTip wrong="Lançar receita no mês errado" right="Use o mês da venda, não o da entrada em caixa." /><ErrorTip wrong="Classificar ferramenta como marketing" right="Use Tecnologia & Ferramentas." /><ErrorTip wrong="Esquecer o centro de resultado" right="Selecione o centro correto." /></div></Card><Card className="rounded-xl p-5"><h2 className="text-xl font-black text-brand-teal">Quando falar com Ryan / Juliana</h2><div className="mt-4 space-y-3 text-sm font-semibold text-brand-teal/70"><p><strong>Na dúvida sobre classificação:</strong> não tem problema perguntar.</p><p><strong>Lançamento fora do padrão:</strong> investimentos, empréstimos e situações pontuais.</p><p><strong>Algo lançado errado:</strong> avise para corrigirmos juntos.</p></div></Card></div></div>; }
function ToneIcon({ tone, Icon }: { tone: "teal" | "green" | "rose" | "gold" | "blue" | "violet"; Icon: typeof WalletCards }) { const tones = { teal: "bg-[color:var(--ds-primary-soft)] text-[color:var(--ds-primary)]", green: "bg-[color:var(--ds-success-soft)] text-[color:var(--ds-success)]", rose: "bg-[color:var(--ds-danger-soft)] text-[color:var(--ds-danger)]", gold: "bg-[color:var(--ds-warning-soft)] text-[color:var(--ds-warning)]", blue: "bg-[color:var(--ds-info-soft)] text-[color:var(--ds-info)]", violet: "bg-violet-100 text-violet-700" }; return <span className={clsx("flex h-10 w-10 shrink-0 items-center justify-center rounded-full", tones[tone])}><Icon className="h-5 w-5" /></span>; }
function MetricCard({ title, value, detail, tone, Icon }: { title: string; value: string; detail: string; tone: "teal" | "green" | "rose" | "gold" | "blue"; Icon: typeof WalletCards }) { return <Card className="group overflow-hidden rounded-[var(--ds-radius-md)] p-5 shadow-[var(--ds-shadow-sm)] transition hover:-translate-y-0.5 hover:shadow-soft"><div className="flex items-start justify-between gap-4"><div><p className="text-sm font-medium leading-5 text-[color:var(--ds-text-secondary)]">{title}</p><p className="mt-3 text-3xl font-semibold leading-tight tracking-tight text-[color:var(--ds-text)] sm:text-4xl">{value}</p><p className="mt-2 text-xs leading-5 text-[color:var(--ds-text-muted)]">{detail}</p></div><ToneIcon tone={tone} Icon={Icon} /></div><div className={clsx("mt-5 h-1.5 rounded-full", tone === "green" ? "bg-emerald-100" : tone === "rose" ? "bg-rose-100" : tone === "gold" ? "bg-brand-sand/70" : tone === "blue" ? "bg-brand-sky/30" : "bg-brand-teal/10")} /></Card>; }
function MiniMetric({ title, value, tone, Icon }: { title: string; value: string; tone: "green" | "rose" | "gold"; Icon: typeof WalletCards }) { return <Card className="rounded-[var(--ds-radius-md)] p-5 shadow-[var(--ds-shadow-sm)]"><div className="flex items-center gap-4"><ToneIcon tone={tone} Icon={Icon} /><div><p className="text-sm font-medium text-[color:var(--ds-text-secondary)]">{title}</p><p className="mt-1 text-2xl font-semibold text-[color:var(--ds-text)]">{value}</p></div></div></Card>; }
function FlowChart({ rows, compact = false }: { rows: Array<{ month: string; entradas: number; saidas: number; saldo: number }>; compact?: boolean }) {
  const width = 720;
  const height = compact ? 220 : 280;
  const pad = { top: 24, right: 26, bottom: 44, left: 58 };
  const values = rows.flatMap((item) => [item.entradas, item.saidas]);
  const max = Math.max(...values, 1);
  const innerWidth = width - pad.left - pad.right;
  const innerHeight = height - pad.top - pad.bottom;
  const x = (index: number) => pad.left + (rows.length <= 1 ? innerWidth / 2 : (index / (rows.length - 1)) * innerWidth);
  const y = (value: number) => pad.top + innerHeight - (value / max) * innerHeight;
  const points = (key: "entradas" | "saidas") => rows.map((item, index) => ({ x: x(index), y: y(item[key]), value: item[key], month: item.month }));
  const path = (key: "entradas" | "saidas") => points(key).map((point, index) => `${index === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
  const area = (key: "entradas" | "saidas") => {
    const series = points(key);
    if (!series.length) return "";
    return `${path(key)} L ${series.at(-1)!.x.toFixed(2)} ${height - pad.bottom} L ${series[0].x.toFixed(2)} ${height - pad.bottom} Z`;
  };
  const labelEvery = rows.length <= 6 ? 1 : Math.ceil(rows.length / 6);
  return <div className={clsx("rounded-2xl bg-gradient-to-b from-white to-brand-cream/45 p-4", compact ? "min-h-[220px]" : "min-h-[300px]")}><svg role="img" aria-label="Fluxo de caixa em linhas, com entradas e saídas por mês" viewBox={`0 0 ${width} ${height}`} className="h-full min-h-[220px] w-full overflow-visible"><defs><linearGradient id="finance-entry-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#10B981" stopOpacity="0.22" /><stop offset="100%" stopColor="#10B981" stopOpacity="0.02" /></linearGradient><linearGradient id="finance-exit-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#C77A4A" stopOpacity="0.16" /><stop offset="100%" stopColor="#C77A4A" stopOpacity="0.01" /></linearGradient></defs>{[0, 0.25, 0.5, 0.75, 1].map((tick) => { const lineY = pad.top + innerHeight * tick; const value = max * (1 - tick); return <g key={tick}><line x1={pad.left} x2={width - pad.right} y1={lineY} y2={lineY} stroke="currentColor" className="text-brand-sand/80" strokeWidth="1" /><text x={pad.left - 12} y={lineY + 4} textAnchor="end" className="fill-brand-teal/45 text-[11px] font-semibold">{money(value, true)}</text></g>; })}<line x1={pad.left} x2={pad.left} y1={pad.top} y2={height - pad.bottom} stroke="currentColor" className="text-brand-sand" /><line x1={pad.left} x2={width - pad.right} y1={height - pad.bottom} y2={height - pad.bottom} stroke="currentColor" className="text-brand-sand" />{rows.length ? <><path d={area("entradas")} fill="url(#finance-entry-fill)" /><path d={area("saidas")} fill="url(#finance-exit-fill)" /><path d={path("entradas")} fill="none" stroke="#10B981" strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" /><path d={path("saidas")} fill="none" stroke="#C77A4A" strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" /></> : null}{rows.map((item, index) => { const showLabel = index % labelEvery === 0 || index === rows.length - 1; return <g key={item.month}><line x1={x(index)} x2={x(index)} y1={pad.top} y2={height - pad.bottom} stroke="currentColor" className="text-brand-sand/45" strokeDasharray="4 8" />{showLabel ? <text x={x(index)} y={height - 16} textAnchor="middle" className="fill-brand-teal/55 text-[12px] font-semibold">{monthLabel(item.month)}</text> : null}</g>; })}{points("entradas").map((point) => <circle key={`entrada-${point.month}`} cx={point.x} cy={point.y} r="5.5" fill="#10B981" stroke="white" strokeWidth="3"><title>{`${monthLabel(point.month)} · Entradas ${money(point.value)}`}</title></circle>)}{points("saidas").map((point) => <circle key={`saida-${point.month}`} cx={point.x} cy={point.y} r="5.5" fill="#C77A4A" stroke="white" strokeWidth="3"><title>{`${monthLabel(point.month)} · Saídas ${money(point.value)}`}</title></circle>)}</svg></div>;
}
function FlowBar({ item, compact = false }: { item: { month: string; entradas: number; saidas: number; saldo: number }; compact?: boolean }) { const max = Math.max(item.entradas, item.saidas, 1); return <div className="space-y-2"><div className="flex items-center justify-between gap-3 text-sm"><span className="font-black text-brand-teal">{monthLabel(item.month)}</span><span className={clsx("font-black", item.saldo >= 0 ? "text-emerald-700" : "text-brand-clay")}>{money(item.saldo, true)}</span></div><div className="grid gap-2"><Bar label="Entradas" value={item.entradas} max={max} className="bg-emerald-500" compact={compact} /><Bar label="Saídas" value={item.saidas} max={max} className="bg-brand-clay" compact={compact} /></div></div>; }
function Bar({ label, value, max, className, compact }: { label: string; value: number; max: number; className: string; compact?: boolean }) { return <div className="grid grid-cols-[78px_minmax(0,1fr)_95px] items-center gap-3 text-xs font-bold text-brand-teal/60"><span>{label}</span><div className={clsx("overflow-hidden rounded-full bg-brand-cream", compact ? "h-2" : "h-3")}><div className={clsx("h-full rounded-full", className)} style={{ width: `${Math.max(4, (value / max) * 100)}%` }} /></div><span className="text-right">{money(value, true)}</span></div>; }
function MovementList({ title, rows, maps, empty, onOpen, onSeeAll }: { title: string; rows: FinLancamento[]; maps: Maps; empty: string; onOpen: (row: FinLancamento) => void; onSeeAll: () => void }) { return <Card className="rounded-xl p-5"><div className="flex items-center justify-between gap-3"><h2 className="text-xl font-black text-brand-teal">{title}</h2><button type="button" onClick={onSeeAll} className="text-sm font-black text-brand-clay">Ver todos</button></div><div className="mt-4 space-y-3">{rows.map((row) => <button key={row.id} type="button" onClick={() => onOpen(row)} className="grid w-full gap-2 rounded-xl border border-brand-sand/70 bg-white/70 p-4 text-left transition hover:bg-white sm:grid-cols-[1fr_auto]"><div><p className="font-black text-brand-teal">{row.descricao}</p><p className="mt-1 text-sm font-semibold text-brand-teal/55">{maps.categoriaById.get(row.categoria_id)?.nome ?? "Sem categoria"} · {dateLabel(row.data_vencimento ?? row.data_pagamento)}</p></div><p className={clsx("text-lg font-black", row.tipo === "entrada" ? "text-emerald-700" : "text-brand-clay")}>{money(row.valor)}</p></button>)}{rows.length === 0 ? <EmptyState text={empty} /> : null}</div></Card>; }
function AttentionItem({ title, detail, active, onClick }: { title: string; detail: string; active: boolean; onClick: () => void }) { return <button type="button" onClick={onClick} className="group grid w-full grid-cols-[auto_1fr_auto] items-center gap-3 rounded-2xl border border-brand-sand/70 bg-white/75 p-4 text-left transition hover:-translate-y-0.5 hover:bg-white hover:shadow-soft"><span className={clsx("flex h-10 w-10 items-center justify-center rounded-full", active ? "bg-rose-100 text-brand-clay" : "bg-emerald-100 text-emerald-700")}><span className="h-2.5 w-2.5 rounded-full bg-current" /></span><div><p className="font-black text-brand-teal">{title}</p><p className="mt-1 text-sm font-semibold text-brand-teal/55">{detail}</p></div><ChevronRight className="h-5 w-5 text-brand-teal/35 transition group-hover:translate-x-0.5 group-hover:text-brand-teal" /></button>; }
function LancamentoRow({ row, maps, canEdit, highlighted, onEdit, onDelete, onBaixar }: { row: FinLancamento; maps: Maps; canEdit: boolean; highlighted: boolean; onEdit: () => void; onDelete: () => void; onBaixar: () => void }) { const category = maps.categoriaById.get(row.categoria_id)?.nome ?? "Sem categoria"; const sub = maps.subcategoriaById.get(row.subcategoria_id ?? "")?.nome; const pending = isPendingClassification(row); return <div data-lancamento-id={row.id} className={clsx("grid gap-3 border-t border-brand-sand/55 px-5 py-5 transition md:grid-cols-[1.1fr_0.8fr_0.8fr_0.8fr_0.7fr_auto] md:items-center", highlighted ? "bg-brand-sand/40 ring-2 ring-brand-clay/35" : pending ? "bg-amber-50/70" : "bg-white/35 hover:bg-white/70")}><div><div className="flex flex-wrap items-center gap-2"><p className="font-black text-brand-teal">{row.descricao}</p>{pending ? <span className="rounded-full bg-brand-sand px-2.5 py-1 text-xs font-black text-brand-teal">Precisa de classificação</span> : null}</div><p className="mt-1 text-xs font-semibold text-brand-teal/50">{maps.centroById.get(row.centro_resultado_id)?.nome ?? "Sem centro"}</p></div><div><p className="text-sm font-bold text-brand-teal">{category}</p><p className="text-xs font-semibold text-brand-teal/50">{sub ?? "Sem subcategoria"}</p></div><div className="text-sm font-bold text-brand-teal/70"><p>{dateLabel(row.data_pagamento)}</p><p className="text-xs text-brand-teal/45">Competência {monthLabel(row.mes_competencia)}</p></div><div><span className={clsx("rounded-full px-3 py-1 text-xs font-black", row.status === "realizado" ? "bg-emerald-50 text-emerald-700" : statusLabel(row) === "Vencido" ? "bg-rose-50 text-brand-clay" : "bg-brand-cream text-brand-teal/65")}>{statusLabel(row)}</span></div><p className={clsx("font-black", row.tipo === "entrada" ? "text-emerald-700" : "text-brand-clay")}>{money(row.valor)}</p><div className="flex flex-wrap gap-2">{canEdit && row.status === "previsto" ? <Button variant="secondary" className="h-9 px-3" onClick={onBaixar}><CheckCircle2 className="h-4 w-4" />Baixar</Button> : null}{canEdit ? <Button variant="secondary" className="h-9 px-3" onClick={onEdit}>{pending ? "Classificar" : <Pencil className="h-4 w-4" />}</Button> : null}{canEdit ? <Button variant="ghost" className="h-9 px-3 text-brand-clay" onClick={onDelete}>Excluir</Button> : null}</div></div>; }
function Pager({ page, totalPages, setPage }: { page: number; totalPages: number; setPage: (page: number) => void }) { return <div className="mt-5 flex items-center justify-end gap-2"><Button variant="secondary" disabled={page <= 1} onClick={() => setPage(page - 1)}>Anterior</Button><span className="text-sm font-bold text-brand-teal/60">{page} / {totalPages}</span><Button variant="secondary" disabled={page >= totalPages} onClick={() => setPage(page + 1)}>Próxima</Button></div>; }
function SummaryList({ title, rows }: { title: string; rows: Array<{ label: string; entradas: number; saidas: number; saldo: number; count: number }> }) { return <Card className="rounded-2xl p-6"><h3 className="text-xl font-black text-brand-teal">{title}</h3><div className="mt-5 space-y-3">{rows.map((row) => <div key={row.label} className="rounded-2xl border border-brand-sand/65 bg-white/65 p-4 transition hover:bg-white"><div className="flex items-start justify-between gap-3"><div><p className="font-black text-brand-teal">{row.label}</p><p className="mt-1 text-xs font-semibold text-brand-teal/50">{row.count} lançamento(s)</p></div><p className={clsx("font-black", row.saldo >= 0 ? "text-emerald-700" : "text-brand-clay")}>{money(row.saldo, true)}</p></div><div className="mt-3 grid grid-cols-2 gap-2 text-xs font-bold text-brand-teal/55"><span>Entradas {money(row.entradas, true)}</span><span>Saídas {money(row.saidas, true)}</span></div></div>)}</div></Card>; }
function AdminStat({ title, value, detail, tone, Icon }: { title: string; value: string; detail: string; tone: "violet" | "blue" | "green" | "gold" | "rose"; Icon: typeof WalletCards }) { const tones = { violet: "bg-violet-100 text-violet-700", blue: "bg-brand-sky/30 text-brand-teal", green: "bg-emerald-100 text-emerald-700", gold: "bg-brand-sand/70 text-brand-teal", rose: "bg-rose-100 text-brand-clay" }; return <Card className="rounded-xl p-5"><div className="flex gap-4"><span className={clsx("flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl", tones[tone])}><Icon className="h-7 w-7" /></span><div><h3 className="font-black text-brand-teal">{title}</h3><p className="mt-1 text-xs font-semibold leading-5 text-brand-teal/55">{detail}</p><p className="mt-3 text-3xl font-black text-brand-teal">{value}</p></div></div></Card>; }
function IntegrationRow({ name, detail, status, tone }: { name: string; detail: string; status: string; tone: "green" | "blue" | "gold" }) { return <div className="grid grid-cols-[1fr_auto] items-center gap-3 border-b border-brand-sand/60 pb-3 last:border-b-0 last:pb-0"><div><p className="font-black text-brand-teal">{name}</p><p className="text-xs font-semibold text-brand-teal/55">{detail}</p></div><span className={clsx("rounded-full px-3 py-1 text-xs font-black", tone === "green" ? "bg-emerald-50 text-emerald-700" : tone === "gold" ? "bg-amber-50 text-amber-700" : "bg-brand-sky/25 text-brand-teal")}>{status}</span></div>; }
function ValidationMini({ label, count, tone }: { label: string; count: number; tone: "green" | "gold" | "rose" }) { return <div className="rounded-xl border border-brand-sand/70 bg-white/70 p-4"><p className="text-sm font-black text-brand-teal">{label}</p><p className={clsx("mt-2 text-3xl font-black", tone === "green" ? "text-emerald-700" : tone === "gold" ? "text-amber-700" : "text-brand-clay")}>{count}</p></div>; }
function ConceptCard({ Icon, title, text, tone }: { Icon: typeof WalletCards; title: string; text: string; tone: "green" | "rose" | "blue" | "gold" }) { const tones = { green: "bg-emerald-100 text-emerald-700", rose: "bg-rose-100 text-brand-clay", blue: "bg-brand-sky/30 text-brand-teal", gold: "bg-brand-sand/70 text-brand-teal" }; return <Card className="rounded-xl p-5"><div className="flex gap-4"><span className={clsx("flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl", tones[tone])}><Icon className="h-7 w-7" /></span><div><h3 className="font-black text-brand-teal">{title}</h3><p className="mt-2 text-sm font-semibold leading-6 text-brand-teal/60">{text}</p><p className="mt-2 text-sm font-black text-brand-clay">Ver exemplos →</p></div></div></Card>; }
function ErrorTip({ wrong, right }: { wrong: string; right: string }) { return <div className="grid gap-2 md:grid-cols-[1fr_auto_1fr] md:items-center"><p className="rounded-lg bg-rose-50 p-3 text-sm font-bold text-brand-teal">{wrong}</p><span className="text-center font-black text-emerald-700">→</span><p className="rounded-lg bg-emerald-50 p-3 text-sm font-bold text-brand-teal">{right}</p></div>; }

function EmptyState({ text }: { text: string }) { return <div className="rounded-md border border-dashed border-brand-sand bg-white/40 p-5 text-sm font-semibold text-brand-teal/55">{text}</div>; }
function buildMonthlyFlow(rows: FinLancamento[]) { const map = new Map<string, { month: string; entradas: number; saidas: number; saldo: number }>(); for (const row of rows.filter((item) => item.status === "realizado")) { const month = (row.data_realizacao ?? row.data_pagamento).slice(0, 7); const item = map.get(month) ?? { month, entradas: 0, saidas: 0, saldo: 0 }; if (row.tipo === "entrada") item.entradas += row.valor; else item.saidas += row.valor; item.saldo = item.entradas - item.saidas; map.set(month, item); } return [...map.values()].sort((a, b) => a.month.localeCompare(b.month)); }
function groupTotals(rows: FinLancamento[], getLabel: (row: FinLancamento) => string) { const map = new Map<string, { label: string; entradas: number; saidas: number; saldo: number; count: number }>(); for (const row of rows.filter((item) => item.status !== "cancelado")) { const label = getLabel(row); const item = map.get(label) ?? { label, entradas: 0, saidas: 0, saldo: 0, count: 0 }; item.count += 1; if (row.tipo === "entrada") item.entradas += row.valor; else item.saidas += row.valor; item.saldo = item.entradas - item.saidas; map.set(label, item); } return [...map.values()].sort((a, b) => Math.abs(b.saldo) - Math.abs(a.saldo)).slice(0, 10); }
function Field({ label, value, onChange, compact = false, className, ...props }: { label: string; value: string; onChange: (value: string) => void; compact?: boolean; className?: string } & Omit<InputHTMLAttributes<HTMLInputElement>, "value" | "onChange">) { return <label className={clsx("block", compact ? "min-w-[220px]" : "", className)}><span className="mb-1 block text-sm font-bold text-brand-teal">{label}</span><input {...props} value={value} onChange={(event) => onChange(event.target.value)} className="h-11 w-full rounded-md border border-brand-sand bg-white/75 px-3 text-sm font-semibold text-brand-teal outline-none transition focus:border-brand-clay disabled:bg-brand-cream/50 disabled:text-brand-teal/45" /></label>; }
function Select({ label, value, onChange, options, compact = false, disabled = false }: { label?: string; value: string; onChange: (value: string) => void; options: Array<[string, string]>; compact?: boolean; disabled?: boolean }) { const input = <select value={value} onChange={(event) => onChange(event.target.value)} disabled={disabled} className="h-11 w-full rounded-md border border-brand-sand bg-white/75 px-3 text-sm font-semibold text-brand-teal outline-none transition focus:border-brand-clay disabled:bg-brand-cream/50 disabled:text-brand-teal/45">{options.map(([optionValue, optionLabel]) => <option key={optionValue} value={optionValue}>{optionLabel}</option>)}</select>; if (!label) return input; return <label className={clsx("block", compact ? "min-w-[190px]" : "")}><span className="mb-1 block text-sm font-bold text-brand-teal">{label}</span>{input}</label>; }


